1", "type": "concept", "title": "Baal Shem Tov"}, {"id": "350dda16-97de-4740-bcea-56914d245d1e", "type": "concept", "title": "Hasidic courts"}, {"id": "b19118a6-b27c-4695-950a-9efc628fb118", "type": "concept", "title": "Rebbe"}, {"id": "a6c7a96c-ab34-4602-b467-a41854944095", "type": "concept", "title": "Devekut"}, {"id": "2eccd6a5-0359-4d21-8beb-355143cf0c6e", "type": "concept", "title": "Nigun"}, {"id": "e292806b-24de-4744-bdd9-05b855223fb3", "type": "concept", "title": "Mitnagdim"}, {"id": "d53c61ab-dcd1-4361-b074-67a6ad3da9ac", "type": "concept", "title": "Chabad"}, {"id": "78815629-3262-4d7c-b85d-067558d14015", "type": "concept", "title": "Lithuanian yeshivot"}], "description": "The point is to see modern Judaism as plural, not simply secularizing."}]}, {"id": "28947c0d-a83b-4bbd-92b3-c0458800d2df", "type": "topic", "title": "Antisemitism, Holocaust, and Jewish Memory", "description": "Modern Jewish history cannot be studied responsibly without antisemitism and the Holocaust, but Jewish history must not be reduced to persecution. This unit studies hatred, catastrophe, resistance, survival, and memory.", "children": [{"id": "5956e389-e14f-4369-a736-5de7433b51fd", "type": "subtopic", "title": "Modern antisemitism", "children": [{"id": "be08fd18-c0e2-43ac-80e0-76147b5fb223", "type": "concept", "title": "Anti-Judaism"}, {"id": "d80532c6-998c-4623-b188-f100bcddfa22", "type": "concept", "title": "Racial antisemitism"}, {"id": "be245f18-a1dc-4197-9d07-b5e48fe28375", "type": "concept", "title": "Dreyfus Affair"}, {"id": "290ef3af-d6fc-44db-a138-19c8b4197d7e", "type": "concept", "title": "Protocols of the Elders of Zion"}, {"id": "2ddbf047-e6ac-490b-ac74-6ab495d9c40c", "type": "concept", "title": "Pogroms"}, {"id": "af45a183-6863-4410-8d27-ef292188b094", "type": "concept", "title": "Scapegoating"}, {"id": "6b403991-6878-4a7d-a6a1-e3552666da9e", "type": "concept", "title": "Conspiracy theories"}, {"id": "cf9a351a-1c53-40bd-976c-32b3ca920241", "type": "concept", "title": "Antisemitism today"}], "description": "Students distinguish religious anti-Judaism from racial, political, and conspiratorial antisemitism."}, {"id": "ef9a4b78-3f5c-4a3f-a992-7c0f197aa19c", "type": "subtopic", "title": "Holocaust history", "children": [{"id": "382c13d7-e776-440d-84b5-260a8dc48105", "type": "concept", "title": "Nazi ideology"}, {"id": "5e97152b-960b-47f2-aee6-b1acdbc46177", "type": "concept", "title": "Nuremberg Laws"}, {"id": "34a83703-cba4-44c4-88e9-4bc442d707b5", "type": "concept", "title": "Ghettos"}, {"id": "730061a2-16c8-4a6c-8974-d0cbfbd0bfb2", "type": "concept", "title": "Einsatzgruppen"}, {"id": "cf594e37-ea5b-4a51-be82-7a3400ca8c74", "type": "concept", "title": "Deportations"}, {"id": "b76251b8-a665-4299-b5ae-c880c7517895", "type": "concept", "title": "Camps"}, {"id": "3b074240-8e39-4d11-bb92-1f426cda33fb", "type": "concept", "title": "Final Solution"}, {"id": "4db9f228-7445-48ce-a4e7-2b7581f2d2e3", "type": "concept", "title": "Resistance"}, {"id": "bf5571e3-fa17-4ecd-baa5-4c72920192f4", "type": "concept", "title": "Survivors"}], "description": "Students learn the events, institutions, victims, perpetrators, bystanders, rescuers, and resistors of the Shoah."}, {"id": "c657e94c-8cb2-400e-af20-8c9fcd7d3568", "type": "subtopic", "title": "Memory and ethics", "children": [{"id": "21c600af-6a07-441c-9baf-1b0e00082bfd", "type": "concept", "title": "Yad Vashem"}, {"id": "fc2d5b6f-8a9c-4cca-9f09-324b248bdf9a", "type": "concept", "title": "Testimony"}, {"id": "d6f21ed6-882d-407e-8e5b-7ab008ca9ad1", "type": "concept", "title": "Memorials"}, {"id": "ff508261-c9f9-4d55-9e92-0af1cdd9b8e6", "type": "concept", "title": "Museums"}, {"id": "3863c313-bf83-41e0-bbfd-3991878692bf", "type": "concept", "title": "Yom HaShoah"}, {"id": "a9638cad-c8a3-486d-b2cb-52415f739225", "type": "concept", "title": "Postmemory"}, {"id": "cc049307-3fd2-454b-9550-79bfdbaae93d", "type": "concept", "title": "Denial"}, {"id": "3a78b402-7311-499f-8f79-2c894ca6e9f2", "type": "concept", "title": "Comparative genocide"}, {"id": "b919ee6f-981e-49e7-acc4-125c0ce6e286", "type": "concept", "title": "Trauma"}], "description": "The point is to study remembrance as historical practice, ethical obligation, and public debate."}]}, {"id": "8a9c302c-b2de-4715-9d6b-4a58d4bbbff6", "type": "topic", "title": "Zionism and Israel", "description": "Zionism and the State of Israel are central to modern Jewish history and identity, but they are also internally diverse and contested. Students learn movements, institutions, debates, and diaspora relationships.", "children": [{"id": "491f4d2e-4cc3-4bfb-9dab-37a9b4f8d141", "type": "subtopic", "title": "Zionist movements", "children": [{"id": "54618764-c101-4fb0-8fe7-05b1f52c6814", "type": "concept", "title": "Theodor Herzl"}, {"id": "748dc1e8-6170-4203-a48c-e07dbc7ea549", "type": "concept", "title": "Political Zionism"}, {"id": "e9c0e759-4709-48af-a2d4-cce206ca2293", "type": "concept", "title": "Cultural Zionism"}, {"id": "7c5d1c1f-f484-4a3d-b9ee-cf62f2089892", "type": "concept", "title": "Labor Zionism"}, {"id": "537b9c90-5725-4d12-a339-b8a41b62ea29", "type": "concept", "title": "Religious Zionism"}, {"id": "e1de8f8d-a5b7-42ed-92af-75eba9eb9220", "type": "concept", "title": "Revisionist Zionism"}, {"id": "4655f22c-caa9-4707-9806-460605952ec4", "type": "concept", "title": "Aliyah"}, {"id": "452fd3b4-c7bd-4aec-950a-94486b733a5b", "type": "concept", "title": "Hebrew revival"}], "description": "Students learn the varieties of Zionism and the historical conditions that shaped them."}, {"id": "69c69a46-f273-424d-a998-810c90955412", "type": "subtopic", "title": "State formation and Israeli society", "children": [{"id": "abaa19f9-80ac-463f-a261-2166883bd8f8", "type": "concept", "title": "Yishuv"}, {"id": "15d82fa9-2042-4b1d-9d79-a22044518c5c", "type": "concept", "title": "British Mandate"}, {"id": "43a56e2e-43b9-451c-888b-76ce14665154", "type": "concept", "title": "1948 war"}, {"id": "e78e1840-c5c0-4607-8e1a-9d09fb23588b", "type": "concept", "title": "Declaration of Independence"}, {"id": "b8ae8f58-8b5a-47d7-bea8-1ae6437241c9", "type": "concept", "title": "Knesset"}, {"id": "f673efcc-4451-445a-857e-523b72ce20dc", "type": "concept", "title": "Law of Return"}, {"id": "74c82821-7af6-441f-a576-b1bebfdee653", "type": "concept", "title": "Mizrahi immigration"}, {"id": "c537f004-d670-4b41-a005-a3d20875c21b", "type": "concept", "title": "Ethiopian Israelis"}, {"id": "1720ef39-d0a4-468b-a5cb-f5c13d4c7191", "type": "concept", "title": "Russian-speaking Israelis"}], "description": "Students examine institutions, conflicts, migrations, and social diversity."}, {"id": "2ebacc57-ee2b-44f5-9659-679f3c5e1d18", "type": "subtopic", "title": "Israel and diaspora", "children": [{"id": "9b78b83c-07cb-49ae-b32e-6c510aedf161", "type": "concept", "title": "Diaspora relations"}, {"id": "1950161e-de9a-4b04-8f68-1a42f802fca4", "type": "concept", "title": "Israel-Palestine conflict"}, {"id": "630d56fb-b15c-4b6d-aaf3-f1f27b559184", "type": "concept", "title": "Jerusalem"}, {"id": "35440bd8-6b72-4d84-8de5-1c8774eec493", "type": "concept", "title": "Settlements"}, {"id": "38584d54-8e32-4af9-afde-14289960354d", "type": "concept", "title": "Peace process"}, {"id": "e6ad0b81-767e-4bdc-a7c4-05f66f419b9d", "type": "concept", "title": "Jewish peoplehood"}, {"id": "0e14136f-ef48-433b-a221-0ee1bd333bc2", "type": "concept", "title": "Criticism of Israel"}, {"id": "42314fe5-2bee-4037-993d-688b57b82e42", "type": "concept", "title": "Antisemitism debates"}], "description": "The goal is to understand Israel as a religious, political, cultural, and ethical question in Jewish life."}]}, {"id": "0c875957-b7ec-4ea8-b2b1-8823bc918363", "type": "topic", "title": "American Judaism and Denominational Life", "description": "American Judaism developed through immigration, religious innovation, suburbanization, civil rights, denominational institutions, and cultural creativity. Students learn how American Jewish life became diverse and dynamic.", "children": [{"id": "51f64105-73f2-449d-9561-c1b22285a381", "type": "subtopic", "title": "Immigration and community formation", "children": [{"id": "967f8028-b42c-47e3-a1bc-86836286a89a", "type": "concept", "title": "Sephardi beginnings"}, {"id": "4e859d9c-ad87-4179-950f-dd7275f6274c", "type": "concept", "title": "German Jewish immigration"}, {"id": "880eccd4-b7c5-4c8d-8889-0a29a4b955f2", "type": "concept", "title": "Eastern European immigration"}, {"id": "e5d308d9-3487-4155-8874-bd9998e2b6e0", "type": "concept", "title": "Lower East Side"}, {"id": "b8c12962-5747-41e5-9899-9a55f4b9e653", "type": "concept", "title": "Landsmanshaftn"}, {"id": "e8c51900-d7e0-472c-8afe-acc9c8e3ccf4", "type": "concept", "title": "Synagogues"}, {"id": "71116012-11f1-42bf-b57d-e08d41d7897a", "type": "concept", "title": "Jewish press"}, {"id": "551b4e6b-0490-45b6-a07e-face30778c32", "type": "concept", "title": "Philanthropy"}], "description": "Students learn the waves and institutions that shaped Jewish life in the United States."}, {"id": "50a72f5a-b429-49ad-8f03-68b1747292fd", "type": "subtopic", "title": "Denominations and institutions", "children": [{"id": "b15e16ea-f916-4922-a989-2100a27ad75c", "type": "concept", "title": "Reform Judaism"}, {"id": "bbe9c8ac-3516-407a-bec1-70f5194a8b92", "type": "concept", "title": "Conservative Judaism"}, {"id": "693b2351-6a94-4eca-afaf-3c21dfafd71a", "type": "concept", "title": "Orthodox Judaism"}, {"id": "4ee252fb-0d10-40ee-9e8f-1d745197e703", "type": "concept", "title": "Reconstructionism"}, {"id": "667a8af8-564c-43e8-a4b7-14eeb31d4125", "type": "concept", "title": "Renewal"}, {"id": "5dfc593f-899f-474f-8514-750f302cef7e", "type": "concept", "title": "Humanistic Judaism"}, {"id": "2677e823-3df8-4bc4-b870-03b8d61d0350", "type": "concept", "title": "JCCs"}, {"id": "2cd3cf60-92cb-4dfe-be89-b383460e4cec", "type": "concept", "title": "Federations"}], "description": "Students examine American Jewish religious movements and their organizations."}, {"