set
  title = 'Judaism',
  goal = 'Judaism',
  summary = 'Study Judaism through academic methods, internal diversity, and core sources from biblical and ancient Israelite backgrounds through Second Temple sects, rabbinic literature, law, ritual, calendar, and embodied life-cycle practice. Coverage continues through medieval thought, Kabbalah, Ashkenazi, Sephardi, and Mizrahi diaspora communities, Jews under Christianity and Islam, modernity and emancipation, antisemitism and Holocaust memory, Zionism and Israel, American denominational life, ethics, contemporary identities, and a research capstone.',
  data = $judjson${"slug": "judaism", "title": "Judaism", "description": "Study Judaism through academic methods, internal diversity, and core sources from biblical and ancient Israelite backgrounds through Second Temple sects, rabbinic literature, law, ritual, calendar, and embodied life-cycle practice. Coverage continues through medieval thought, Kabbalah, Ashkenazi, Sephardi, and Mizrahi diaspora communities, Jews under Christianity and Islam, modernity and emancipation, antisemitism and Holocaust memory, Zionism and Israel, American denominational life, ethics, contemporary identities, and a research capstone.", "topics": [{"id": "79a6321a-0bf3-48c6-ac72-5ae4ef092053", "type": "topic", "title": "Studying Judaism: Methods, Diversity, and Sources", "description": "This opening unit frames Judaism as a historically changing, textually rich, ritually embodied, and internally diverse tradition. Students learn how academic study differs from devotional, communal, or polemical accounts while still taking lived Jewish practice seriously.", "children": [{"id": "32893eab-c861-49ce-9519-617536bb5759", "type": "subtopic", "title": "Academic approaches to Judaism", "children": [{"id": "3c4338eb-5eac-4105-b14f-14b8b95caaa5", "type": "concept", "title": "Religious studies method"}, {"id": "743abce3-c988-4813-95e4-10a4f81c08ed", "type": "concept", "title": "History of religions"}, {"id": "dc04cfbc-2b35-4270-ae62-0688824b1f96", "type": "concept", "title": "Ethnography"}, {"id": "baf64e4c-03b5-4d8f-953c-09d0159fa584", "type": "concept", "title": "Textual criticism"}, {"id": "01b9e0fa-8d2c-41dd-aec6-7dc8264bfc00", "type": "concept", "title": "Material culture"}, {"id": "6380f40e-6a21-4765-8c55-406951a178fa", "type": "concept", "title": "Lived religion"}, {"id": "4a29229e-7d7b-4ff9-a8f6-0dc8fa84d756", "type": "concept", "title": "Insider and outsider perspectives"}, {"id": "bdd55425-5930-434c-96c6-22dd6ffd42d6", "type": "concept", "title": "Translation issues"}], "description": "Students learn the basic tools for studying Judaism through history, texts, communities, rituals, and material culture."}, {"id": "91e85917-f0f5-40f6-9c42-7b35dd5ae692", "type": "subtopic", "title": "Jewish diversity", "children": [{"id": "1497c69b-637a-4c10-8a30-cffc359caa4a", "type": "concept", "title": "Ashkenazi"}, {"id": "9c481f7d-d223-45c2-9f1d-0a5bd7d16557", "type": "concept", "title": "Sephardi"}, {"id": "d101c46d-77e1-45e5-a443-1429479b38b4", "type": "concept", "title": "Mizrahi"}, {"id": "a2794650-437f-4d6b-b158-9fcd419e1eb5", "type": "concept", "title": "Ethiopian Jews"}, {"id": "24bb756e-0d56-4218-abaa-f92f096ce314", "type": "concept", "title": "Denominations"}, {"id": "2c3f532b-2a12-4438-89b1-32cb8e00356e", "type": "concept", "title": "Secular Jews"}, {"id": "540e5144-6533-4c6b-85ff-fb57918f76da", "type": "concept", "title": "Religious Zionist"}, {"id": "c0c6365a-e043-48b3-a073-96f4378e7261", "type": "concept", "title": "Haredi"}, {"id": "a57eae8b-d756-4d66-908b-eec2cd6d0feb", "type": "concept", "title": "Liberal Judaism"}], "description": "The point is to avoid treating Judaism as one uniform belief system."}, {"id": "2add1927-8bd5-4c1d-93a7-5fc0b108d195", "type": "subtopic", "title": "Core source categories", "children": [{"id": "d5af5484-4894-4a05-8246-c070558a770f", "type": "concept", "title": "Tanakh"}, {"id": "54cfdd21-8603-4bf0-a1f2-06b6897acd92", "type": "concept", "title": "Torah"}, {"id": "ab162236-7020-493d-8e8c-5e40e0869910", "type": "concept", "title": "Neviim"}, {"id": "c30ac9ef-f80f-4dd0-9c31-8a9a7975761d", "type": "concept", "title": "Ketuvim"}, {"id": "c142e49b-2491-4315-a409-561ff04951f8", "type": "concept", "title": "Mishnah"}, {"id": "d899a3e6-9289-4351-8029-e6ef57c28d32", "type": "concept", "title": "Talmud"}, {"id": "8eaec960-4da0-4943-8914-cd18af46afba", "type": "concept", "title": "Midrash"}, {"id": "0c2a98d2-c704-4842-b47e-8df35bfa585a", "type": "concept", "title": "Responsa"}, {"id": "7157e937-2d81-4ddc-899b-07efa96707df", "type": "concept", "title": "Siddur"}, {"id": "afc599c5-d6d8-4ba6-b444-bc29b8eb5bf6", "type": "concept", "title": "Commentary"}], "description": "Students learn the map of Jewish textual and historical sources used throughout the course."}]}, {"id": "006a4790-02fa-44f6-b95d-e898ba1986f8", "type": "topic", "title": "Biblical and Ancient Israelite Backgrounds", "description": "Judaism's later forms draw on ancient Israelite traditions, biblical literature, covenantal language, temple practices, and prophetic critique. This unit gives students historical and textual foundations without reducing Judaism to the Bible alone.", "children": [{"id": "7e9b12d3-5354-40b1-9878-fb7e9ef7408c", "type": "subtopic", "title": "Ancient Israel and Judah", "children": [{"id": "acf89038-0286-4549-8772-792fd5ac228f", "type": "concept", "title": "Canaan"}, {"id": "835c0227-fc46-4ddc-b5d9-21973eb19bcf", "type": "concept", "title": "Tribes of Israel"}, {"id": "60f1938d-8770-4cce-95b1-11713000c494", "type": "concept", "title": "United monarchy"}, {"id": "ccc81797-fabd-4bce-87a3-41d4ae54e72c", "type": "concept", "title": "Kingdom of Israel"}, {"id": "66b02301-2021-4978-bf4c-5081f81a72d8", "type": "concept", "title": "Kingdom of Judah"}, {"id": "6de78647-2e11-472e-9ed4-7cd41c432104", "type": "concept", "title": "Assyrian conquest"}, {"id": "8df655f9-a3f7-4e3c-addf-7df0f08925e4", "type": "concept", "title": "Babylonian exile"}, {"id": "31692341-a36c-42bb-96b4-0e81ff411dbb", "type": "concept", "title": "Persian period"}], "description": "Students learn the historical settings behind biblical traditions and Israelite identity formation."}, {"id": "a580b48b-32a0-45c4-bf5f-23ef73eaa6c0", "type": "subtopic", "title": "Biblical texts and genres", "children": [{"id": "a88e0843-b7a7-4bae-847f-4fe2e81efe26", "type": "concept", "title": "Genesis"}, {"id": "84b7497c-2ec6-4c06-a260-51536b251651", "type": "concept", "title": "Exodus"}, {"id": "94b15e0f-fc3a-4a24-ab05-7023a57101c4", "type": "concept", "title": "Deuteronomy"}, {"id": "5856381f-a300-4553-ac77-81c40b124c90", "type": "concept", "title": "Prophets"}, {"id": "e6ed2662-df54-43fb-b034-6eaa85415b93", "type": "concept", "title": "Psalms"}, {"id": "eb07971a-037c-4576-84d4-24127a1abee0", "type": "concept", "title": "Proverbs"}, {"id": "0ec64e34-d5bb-465a-a549-87b7434e8c21", "type": "concept", "title": "Job"}, {"id": "977fcb59-e868-461b-ab3c-11ebd8c709a9", "type": "concept", "title": "Chronicles"}, {"id": "c9a71b32-3d92-49a7-9e37-c6711559261e", "type": "concept", "title": "Canon formation"}], "description": "The goal is to read the Hebrew Bible as a library of law, narrative, poetry, prophecy, wisdom, and memory."}, {"id": "ca90d5f6-dca0-4c24-8446-0d0b4e8899f3", "type": "subtopic", "title": "Covenant, law, and temple", "children": [{"id": "20ab86df-fae1-4af2-8c2b-fee843151956", "type": "concept", "title": "Covenant"}, {"id": "9113afae-e1f8-448d-a6ba-5e6fe95cdbe7", "type": "concept", "title": "Mitzvot"}, {"id": "74a97fcc-c8c8-4cc4-bd69-924a108ed13f", "type": "concept", "title": "Priesthood"}, {"id": "368920ad-f05d-404e-8f51-242b277f4804", "type": "concept", "title": "Sacrifice"}, {"id": "12c73760-1914-46fe-bd58-ac5c1dcfd073", "type": "concept", "title": "Temple"}, {"id": "dd60fb9c-0d2b-476c-ae8e-555ffd7a82da", "type": "concept", "title": "Purity"}, {"id": "75b26642-17ad-4e0a-a085-4d1ec36d3cc0", "type": "concept", "title": "Sabbath"}, {"id": "bcab185d-b130-4a16-9fdf-23a98c9decc7", "type": "concept", "title": "Exile"}, {"id": "8d8fb23d-fc1a-4c49-aa07-6ae6d5d538e5", "type": "concept", "title": "Return"}], "description": "Students learn concepts that later Jewish communities reinterpret in many ways."}]}, {"id": "0f0ef2a9-d111-4359-8f13-a012371dd827", "type": "topic", "title": "Second Temple Judaism and the Emergence of Jewish Sects", "description": "The Second Temple period was a world of diversity, empire, apocalyptic hope, sectarian movements, and scriptural interpretation. Students learn how this period shaped later Judaism and early Christianity.", "children": [{"id": "5526b393-e333-428d-86fd-a0d5e22360fe", "type": "subtopic", "title": "Historical setting", "children": [{"id": "f4dc571f-2f51-49bc-af92-68ece59f0b52", "type": "concept", "title": "Second Temple"}, {"id": "a92b836e-4802-4d9e-989a-ae9ff9c6f39d", "type": "concept", "title": "Hellenism"}, {"id": "805c6ee7-6e4a-41e0-b5de-b557d0df08ef", "type": "concept", "title": "Maccabean revolt"}, {"id": "f048a9d7-8bb2-4b86-8380-c6df75267a9d", "type": "concept", "title": "Hasmoneans"}, {"id": "204269b9-7847-41c0-b261-9d040c08d823", "type": "concept", "title": "Herod"}, {"id": "b666d34f-7bd5-4c77-9d90-846c7dd6773e", "type": "concept", "title": "Roman Judea"}, {"id": "e3dcb73c-fd63-4621-b852-086ea7b8dbc7", "type": "concept", "title": "Diaspora"}, {"id": "0747d43b-a091-49b9-88bb-d8a0f71f2dfb", "type": "concept", "title": "Temple economy"}], "description": "Students understand Jewish life under Persian, Hellenistic, Hasmonean, and Roman power."}, {"id": "25c7a683-314c-4d72-ae8c-3be2118c885e", "type": "subtopic", "title": "Jewish groups and movements", "children": [{"id": "4cbfdaa1-9f49-4b3a-89f5-36a8b865a388", "type": "concept", "title": "Pharisees"}, {"id": "34ad8dc5-03fd-47d6-96ee-edccb8e67bb8", "type": "concept", "title": "Sadducees"}, {"id": "bb1c941b-b7c7-4bb3-9aac-1611bcfa1e37", "type": "concept", "title": "Essenes"}, {"id": "bc20cd0c-2933-4da8-9e35-112d98381e27", "type": "concept", "title": "Zealots"}, {"id": "2fb54ba7-2c92-4466-a6f7-60cc4be51c02", "type": "concept", "title": "Qumran"}, {"id": "2ddc2e0d-6b48-4ef3-8b27-354802c342a3", "type": "concept", "title": "Dead Sea Scrolls"}, {"id": "bc339725-28cf-4b2d-81db-f1d4a49c55db", "type": "concept", "title": "Apocalypticism"}, {"id": "5f1f7931-80fc-4265-803a-eebb6f7e41ce", "type": "concept", "title": "Scribes"}], "description": "Students learn why ancient Judaism was plural and contested."}, {"id": "558a4f54-2e10-4b0b-9ee8-f91fbf93764b", "type": "subtopic", "title": "Interpretation and identity", "children": [{"id": "b76dab36-cc6a-4922-b74b-1b4856d8ced8", "type": "concept", "title": "Torah interpretation"}, {"id": "2097ee85-2f2d-4e1a-92ea-3c86ae1ac5cd", "type": "concept", "title": "Purity practices"}, {"id": "af861967-57a6-4f59-8077-e0b61f8f7879", "type": "concept", "title": "Messianism"}, {"id": "1d92968b-d4c0-4b73-84d1-ca1fab26b90a", "type": "concept", "title": "Resurrection"}, {"id": "d6eb8334-cfe2-4e61-9331-b0035ec0ef0d", "type": "concept", "title": "Synagogue"}, {"id": "7d2386c8-496a-4264-a549-b8a811d835cb", "type": "concept", "title": "Pilgrimage festivals"}, {"id": "58097a67-6b56-425a-91c1-c46a7f70d1fd", "type": "concept", "title": "Sectarian texts"}, {"id": "d98fa867-922d-401e-b2e4-b8149d14a072", "type": "concept", "title": "Boundary markers"}], "description": "The point is to see how scripture, law, purity, and hope for restoration shaped Jewish identities."}]}, {"id": "00d27328-b80e-419c-918f-ebbb14fe4ca4", "type": "topic", "title": "Rabbinic Literature: Mishnah, Talmud, Midrash, and Commentary", "description": "Rabbinic Judaism created a durable culture of study, law, debate, and interpretation after the destruction of the Second Temple. Students learn how rabbinic texts work and why they became central.", "children": [{"id": "d3451185-83f4-434d-b473-00b94aef82a0", "type": "subtopic", "title": "Rabbinic formation", "children": [{"id": "3a3e8263-7449-4bdd-9371-1904d77abad3", "type": "concept", "title": "Destruction of the Second Temple"}, {"id": "65b544de-cdab-4f8b-a01d-7ce8335ebad1", "type": "concept", "title": "Yavneh"}, {"id": "efb1a1e6-b8e1-452f-bf0d-4ebab1e359b2", "type": "concept", "title": "Tannaim"}, {"id": "a9ff2aeb-9105-4e78-8b0a-d9fe3d929c81", "type": "concept", "title": "Amoraim"}, {"id": "36711e3b-78cf-477e-bac9-ace2cc548824", "type": "concept", "title": "Sages"}, {"id": "ff58670a-2d79-496b-b155-9c0ee886a03a", "type": "concept", "title": "Oral Torah"}, {"id": "352c5624-4bc4-4fa7-8437-3b64590abde0", "type": "concept", "title": "Study house"}, {"id": "6d15562d-e63a-46c3-bfea-59a0d4bd3be2", "type": "concept", "title": "Rabbinic authority"}], "description": "Students learn the historical shift from temple-centered practice to rabbinic textual and communal authority."}, {"id": "4c7ec9d7-4bb1-419d-b2ba-60a6d32c6617", "type": "subtopic", "title": "Major rabbinic corpora", "children": [{"id": "75f76f8a-4946-44cd-9aaf-dede9c93538b", "type": "concept", "title": "Mishnah"}, {"id": "4eff8186-d398-4032-9e78-9e506db9f531", "type": "concept", "title": "Tosefta"}, {"id": "d7a9b48d-4849-44c7-93ed-10d5e6b88dcd", "type": "concept", "title": "Jerusalem Talmud"}, {"id": "38926357-1c6f-47dc-bc28-60c47c42dbbe", "type": "concept", "title": "Babylonian Talmud"}, {"id": "d9019f77-2de7-460f-89c0-5149756085eb", "type": "concept", "title": "Midrash halakhah"}, {"id": "e4042068-a6fb-4c0b-804e-5774becc830c", "type": "concept", "title": "Midrash aggadah"}, {"id": "bddf9e85-7adb-49c2-8bdc-4a2f3a42c57e", "type": "concept", "title": "Gemara"}, {"id": "55cd1a3c-cf96-4a15-937f-fbc41a1ece0a", "type": "concept", "title": "Sugya"}], "description": "Students learn the genres and structure of classical rabbinic literature."}, {"id": "6d1d8add-f3fb-4e1b-a5b1-70d13725e3e2", "type": "subtopic", "title": "Reading rabbinic texts", "children": [{"id": "325d3fb8-e37a-4706-aa6e-17b3870bf666", "type": "concept", "title": "Makhloqet"}, {"id": "a1517534-73c0-462b-9c1d-cee697722389", "type": "concept", "title": "Baraita"}, {"id": "ad0f05f0-6908-48eb-a38f-b8492cc9b51b", "type": "concept", "title": "Halakhah"}, {"id": "abbaba81-5a6f-4f46-ae57-74efe32ce2d3", "type": "concept", "title": "Aggadah"}, {"id": "cc2cd125-b455-4209-9846-b4e4241ab81f", "type": "concept", "title": "Prooftext"}, {"id": "8f5f73ea-9093-4f45-8bf0-d5deac961c19", "type": "concept", "title": "Legal fiction"}, {"id": "e2b29cec-02f3-4293-b7cb-07f60641b410", "type": "concept", "title": "Case law"}, {"id": "8ec156d1-45d4-4127-877a-bee528825d9b", "type": "concept", "title": "Commentary tradition"}], "description": "The goal is to understand rabbinic argument as layered interpretation rather than simple rule listing."}]}, {"id": "911612ea-fe24-4231-a6ab-bfd2496b2500", "type": "topic", "title": "Law, Ritual, and Calendar", "description": "Jewish law and ritual organize time, food, bodies, households, public worship, and ethical life. Students learn halakhah as a living interpretive system rather than a static legal code.", "children": [{"id": "5dfeca04-13fd-4c9f-a0d8-d58618a30066", "type": "subtopic", "title": "Halakhic reasoning", "children": [{"id": "0399a369-510e-4931-b937-8fe9dc2e1d6a", "type": "concept", "title": "Halakhah"}, {"id": "066324db-59fa-4f86-a066-78bcdbd9f740", "type": "concept", "title": "Minhag"}, {"id": "c227f7cd-8152-4eb4-b17e-46f450817d66", "type": "concept", "title": "Responsa"}, {"id": "b6e2bb7b-0439-4633-a81b-0a7c5cd69b9f", "type": "concept", "title": "Posek"}, {"id": "5903fec3-b65f-46b1-b2c4-8fdf4ed7c965", "type": "concept", "title": "Shulchan Aruch"}, {"id": "cd17e6e0-7b34-4515-86db-408ff8e8bf87", "type": "concept", "title": "Mishneh Torah"}, {"id": "fbe586ad-717b-4b45-a45c-62456b6ad0a6", "type": "concept", "title": "Legal pluralism"}, {"id": "eb0bda1b-821b-4087-97d5-4272e73f57e2", "type": "concept", "title": "Stringency and leniency"}], "description": "Students learn how Jewish law develops through texts, precedent, custom, and communal authority."}, {"id": "d4093c9c-aa99-4d86-aede-8730f013850b", "type": "subtopic", "title": "Ritual life and practice", "children": [{"id": "5f7a99b6-bf4c-4770-b347-2e09f5dee1f9", "type": "concept", "title": "Shabbat"}, {"id": "008753ed-cea3-4041-9318-cd2649de6029", "type": "concept", "title": "Kashrut"}, {"id": "1b105d0a-ff2b-4dcc-8118-7f23c13f92c1", "type": "concept", "title": "Prayer"}, {"id": "cf7e8fc5-e288-4f62-972a-1b7a4aa6f474", "type": "concept", "title": "Synagogue"}, {"id": "1d6b7e65-1e75-4774-a54f-25a93e69d72c", "type": "concept", "title": "Tallit"}, {"id": "8d371470-b540-48ab-b3f5-9f63d962d15b", "type": "concept", "title": "Tefillin"}, {"id": "43e261e8-0090-486a-b443-cc3f57dbba42", "type": "concept", "title": "Mezuzah"}, {"id": "a10c9e39-66b1-4a7c-bfc5-323f86460196", "type": "concept", "title": "Blessings"}, {"id": "571ffa4f-9b7e-44c9-953e-467ba5c103f2", "type": "concept", "title": "Torah reading"}], "description": "Students learn major practices that structure Jewish daily and communal life."}, {"id": "79e199c9-d7cf-435f-bb24-07a701f73a37", "type": "subtopic", "title": "Jewish calendar", "children": [{"id": "26147b74-85f5-4994-95de-a526d8bc5da2", "type": "concept", "title": "Rosh Hashanah"}, {"id": "f645a0cc-674f-45cd-bf05-ca49046b5e27", "type": "concept", "title": "Yom Kippur"}, {"id": "0b0c883a-49d4-48c4-8dd1-e604688395c4", "type": "concept", "title": "Sukkot"}, {"id": "c88a4778-9df1-4b5c-ad7f-7bb09794afd7", "type": "concept", "title": "Passover"}, {"id": "1077d45d-1e10-4dc1-989f-4705e1308c68", "type": "concept", "title": "Shavuot"}, {"id": "f1b07736-df77-4ff8-b78e-7e64f0298351", "type": "concept", "title": "Hanukkah"}, {"id": "fb55cfcd-7a1a-424b-acdc-14d04a973aee", "type": "concept", "title": "Purim"}, {"id": "594ef383-5a14-43e6-97fc-6bccdb5cf513", "type": "concept", "title": "Tisha B'Av"}, {"id": "fcee8582-57d9-43b3-b2a0-9f95e18edc6a", "type": "concept", "title": "Counting the Omer"}], "description": "The point is to understand sacred time as historical memory, ritual practice, and communal formation."}]}, {"id": "7d395007-9420-41f9-a78c-5d9428df94b2", "type": "topic", "title": "Life Cycle, Family, Gender, and Embodied Practice", "description": "Judaism is lived through bodies, families, households, gender roles, rites of passage, and communal obligations. This unit studies how Jewish identity is formed across the life course.", "children": [{"id": "66a2dd3d-cc9f-486b-a7b6-d548295ec3a6", "type": "subtopic", "title": "Birth, childhood, and coming of age", "children": [{"id": "a0bf8dee-8ad8-48a8-8df4-1274bf435e0f", "type": "concept",