id": "b758b9b3-5c00-4327-a39d-585ee232fe24", "type": "concept", "title": "Kaddish"}, {"id": "a252d5b4-576d-4a68-8b66-1f6d573a183e", "type": "concept", "title": "Shiva"}, {"id": "750270f8-8185-4232-a536-7142287c711c", "type": "concept", "title": "Sheloshim"}, {"id": "c7201bc1-6b38-4ef1-bb27-54f6cf6c4d94", "type": "concept", "title": "Yahrzeit"}, {"id": "648742b9-9b84-458c-abf6-c294cb1558ba", "type": "concept", "title": "Yizkor"}, {"id": "be941ea6-7a97-4d89-929b-3e9d2fd8bcbe", "type": "concept", "title": "Olam ha-ba"}], "description": "The point is to see how Jewish practice organizes grief, community support, and memory."}]}, {"id": "0517f80c-a981-42a1-b66c-ab65d2dada83", "type": "topic", "title": "Medieval Jewish Thought, Philosophy, and Biblical Interpretation", "description": "Medieval Jewish communities produced major works of philosophy, poetry, law, grammar, biblical commentary, and interreligious argument. Students learn how Jewish thinkers engaged Greek philosophy, Islam, Christianity, and Hebrew textual traditions.", "children": [{"id": "1c0b3f5e-63ad-4c92-90aa-bbcc41c72de6", "type": "subtopic", "title": "Jewish philosophy", "children": [{"id": "07c5935a-00f0-442b-b756-31c205c454e2", "type": "concept", "title": "Saadia Gaon"}, {"id": "70d47349-92fd-484d-ace1-9628002787e3", "type": "concept", "title": "Judah Halevi"}, {"id": "9c7f553a-41b1-4bd2-add6-3d1d0162410c", "type": "concept", "title": "Maimonides"}, {"id": "1e463072-730e-40c0-a3c4-f452ba2c88bf", "type": "concept", "title": "Guide of the Perplexed"}, {"id": "a99ff672-1373-405a-8484-d57f3c88584a", "type": "concept", "title": "Aristotelianism"}, {"id": "7a0bf975-7450-427d-8724-0b54a9cf53df", "type": "concept", "title": "Negative theology"}, {"id": "0367a10e-4228-4da0-a56c-57817f729e89", "type": "concept", "title": "Creation"}, {"id": "e78c1cb3-ea05-4222-965a-a1e797e07753", "type": "concept", "title": "Prophecy"}], "description": "Students learn key medieval debates about God, reason, revelation, creation, and law."}, {"id": "e71cc0ff-b221-4dd3-91b7-52f459df54e8", "type": "subtopic", "title": "Commentary and language", "children": [{"id": "ea8e5bb2-8b44-43f4-a664-071d1bace741", "type": "concept", "title": "Rashi"}, {"id": "9b5f2b05-a9c2-4f79-9d36-2864888eded3", "type": "concept", "title": "Ibn Ezra"}, {"id": "2b7ec238-1c5a-4bcb-91b6-1b2388a21d8c", "type": "concept", "title": "Radak"}, {"id": "c966d7d4-3c83-44f1-ad9b-4ba295b1e1b4", "type": "concept", "title": "Nahmanides"}, {"id": "15515460-3f7b-4cb5-b0fb-7844fb975f35", "type": "concept", "title": "Peshat"}, {"id": "20af4543-d3ea-4f03-acd8-b876cdc483d6", "type": "concept", "title": "Derash"}, {"id": "95503d3a-8694-41f2-bef7-c6b5923ea022", "type": "concept", "title": "Hebrew grammar"}, {"id": "b8984e4d-c788-4888-af92-b70a293ac997", "type": "concept", "title": "Masorah"}], "description": "Students learn how biblical interpretation became a central intellectual practice."}, {"id": "9f24a133-2fcb-4c9c-9085-188b82ea1628", "type": "subtopic", "title": "Poetry and culture", "children": [{"id": "470f5beb-4beb-4329-a0d6-a3cc40957ce5", "type": "concept", "title": "Golden Age of Spain"}, {"id": "0bfe28ed-cb63-4ecc-b87e-84aa5e6dc23f", "type": "concept", "title": "Hebrew poetry"}, {"id": "1db86390-2354-42b2-9767-f5df0238a899", "type": "concept", "title": "Piyyut"}, {"id": "5574e18f-75e7-4b94-81f8-e2539388dadc", "type": "concept", "title": "Yehuda Halevi"}, {"id": "0f63c772-30b7-4dce-9f90-11ca0b725f5f", "type": "concept", "title": "Samuel ibn Naghrillah"}, {"id": "ea604ce7-de4e-4f6e-b2cd-c461b4016b11", "type": "concept", "title": "Court Jews"}, {"id": "4b394216-b0d2-4d42-86e2-02576f47f2fa", "type": "concept", "title": "Translation"}, {"id": "13120b0f-2e94-42a2-a28b-1572651bc235", "type": "concept", "title": "Philosophical debate"}], "description": "The point is to recognize Jewish creativity in Arabic, Hebrew, and Romance-language worlds."}]}, {"id": "4361a9cd-71fd-49a5-ae18-48f0362691b8", "type": "topic", "title": "Mysticism and Kabbalah", "description": "Jewish mystical traditions offer symbolic, experiential, and speculative ways of understanding God, creation, Torah, and ritual. Students learn Kabbalah historically and conceptually without treating it as timeless esotericism.", "children": [{"id": "dc539f19-b680-48a5-a7ff-720a0b90ec19", "type": "subtopic", "title": "Early mystical traditions", "children": [{"id": "5085d79c-60ac-4453-a4ba-bd81095d974d", "type": "concept", "title": "Merkavah mysticism"}, {"id": "32c5b1de-d72b-43a4-89b0-fdb378cd84ac", "type": "concept", "title": "Hekhalot literature"}, {"id": "bcd02d9a-7dfc-42ee-9a0c-74b97049ffe6", "type": "concept", "title": "Shiur Qomah"}, {"id": "ff75b4fa-43a4-4e3d-8909-ba67c5b5335a", "type": "concept", "title": "Heavenly ascent"}, {"id": "7ac42390-7d88-4c8e-8aa5-3e2cc31ba467", "type": "concept", "title": "Angels"}, {"id": "e78eb463-290e-42d0-8ebe-6ad3b3c0d450", "type": "concept", "title": "Divine throne"}, {"id": "53933614-3826-4a40-95f6-27a481f3f3fc", "type": "concept", "title": "Secret names"}, {"id": "7d7952fb-d9c5-4e64-ac73-9fe79afbd4d8", "type": "concept", "title": "Ecstatic practice"}], "description": "Students trace Jewish mysticism before classical Kabbalah."}, {"id": "a8163491-6466-4502-ae48-ebb5b9af20c8", "type": "subtopic", "title": "Classical Kabbalah", "children": [{"id": "e487169a-693a-4ff1-aab1-5aa31f028126", "type": "concept", "title": "Zohar"}, {"id": "96aefec4-b63f-48dc-b28b-3fe59d30471e", "type": "concept", "title": "Sefirot"}, {"id": "60d28b9f-5138-4d5e-8053-956ebb85c2b6", "type": "concept", "title": "Ein Sof"}, {"id": "1db74d01-a873-4651-b8b6-d08604d39c9c", "type": "concept", "title": "Shekhinah"}, {"id": "442063ef-053e-456d-81df-0dc3991af554", "type": "concept", "title": "Tikkun"}, {"id": "4363ab28-20a0-454c-9486-625c3b6ee043", "type": "concept", "title": "Sitra achra"}, {"id": "05c02f45-c73d-4d85-b522-d58fba353fad", "type": "concept", "title": "Tree of life"}, {"id": "97d0733e-4d08-4b2a-bc5b-53d8321bfdec", "type": "concept", "title": "Theurgy"}], "description": "Students learn central Kabbalistic symbols and texts."}, {"id": "fee386ba-a1ec-4e6c-bb1c-46dfb8a1b709", "type": "subtopic", "title": "Lurianic and later mysticism", "children": [{"id": "8e5d5c51-bd03-4651-9484-daf52fcfaafc", "type": "concept", "title": "Isaac Luria"}, {"id": "1c8c030a-3dda-4855-88fb-622511e8d827", "type": "concept", "title": "Tzimtzum"}, {"id": "4bd4dde0-649e-456f-8890-2ac551ef624c", "type": "concept", "title": "Shevirat ha-kelim"}, {"id": "7f0fbfe4-04c8-496e-9786-6e4ea86dc6ee", "type": "concept", "title": "Tikkun olam"}, {"id": "2d0b78f8-0145-4935-bd02-89a43c952b2e", "type": "concept", "title": "Sabbateanism"}, {"id": "313ac5d5-531d-46a3-b065-d81c22434c55", "type": "concept", "title": "Hasidism"}, {"id": "fad8d4a6-d65f-4cb7-a423-e23ccccef643", "type": "concept", "title": "Mitnagdim"}, {"id": "aa209326-8457-4b1f-855a-ffac9f5071ee", "type": "concept", "title": "Neo-Hasidism"}], "description": "The goal is to see how mystical ideas shaped ritual, messianism, Hasidism, and modern spirituality."}]}, {"id": "a092756f-3f2e-42cd-89de-7a19747303be", "type": "topic", "title": "Diaspora Communities: Ashkenazi, Sephardi, Mizrahi, and Beyond", "description": "Jewish history is a history of movement, settlement, adaptation, memory, and connection across regions. Students learn the diversity of diaspora Jewish cultures and the limits of Europe-centered narratives.", "children": [{"id": "143c03cc-3216-49a9-b4dd-32722ecf2086", "type": "subtopic", "title": "Ashkenazi worlds", "children": [{"id": "a1bfba38-bdc5-4de2-836f-09d0bc1f7cd6", "type": "concept", "title": "Ashkenaz"}, {"id": "3fee5a7e-7117-4e16-9b59-c452719ca061", "type": "concept", "title": "Yiddish"}, {"id": "c65ca5c6-a3c8-4bfc-9eaf-10ce50827f15", "type": "concept", "title": "Kehillah"}, {"id": "ad44e4f8-8294-474a-a6a4-45a720167eec", "type": "concept", "title": "Shtetl"}, {"id": "e574b903-7b01-401e-8b71-6245d0f1f138", "type": "concept", "title": "Pale of Settlement"}, {"id": "9e53550e-5f37-44be-ad35-eb81a177093e", "type": "concept", "title": "Yeshiva"}, {"id": "c11233bb-e435-4e1e-90a2-3fa9e5de4313", "type": "concept", "title": "Pogroms"}, {"id": "7f739617-ab4a-4ec6-901a-dadb5fba97bf", "type": "concept", "title": "Haskalah"}], "description": "Students learn the development of Jewish life in northern, central, and eastern Europe."}, {"id": "b180c28a-0af1-4308-a80c-d0d386a3c38f", "type": "subtopic", "title": "Sephardi worlds", "children": [{"id": "54eae3dd-d20d-4ddb-8ba0-4ed4ee3a4d12", "type": "concept", "title": "Sepharad"}, {"id": "003eeb4e-2596-496b-bd46-b08ec16e91f3", "type": "concept", "title": "Ladino"}, {"id": "b264a0c3-0aa3-44f0-8a94-938393d93e09", "type": "concept", "title": "Al-Andalus"}, {"id": "e800aacf-2632-43b5-85eb-11e10ef1877f", "type": "concept", "title": "Expulsion of 1492"}, {"id": "262ce249-b020-4036-bdf0-6f8e00d80166", "type": "concept", "title": "Conversos"}, {"id": "3ef45366-1cdf-4944-b5a3-167ef23bb0df", "type": "concept", "title": "Ottoman Jewry"}, {"id": "195dc48c-c258-4ae0-ac68-4afa98afacb5", "type": "concept", "title": "Salonika"}, {"id": "fbac55c2-000f-4ad4-b0f9-bc3e6c28dd5c", "type": "concept", "title": "Amsterdam"}], "description": "Students examine Iberian, Mediterranean, Ottoman, and diasporic Sephardi cultures."}, {"id": "d357f850-6480-4d5e-855f-67ab27f701cf", "type": "subtopic", "title": "Mizrahi and global communities", "children": [{"id": "f9368f52-db38-47d8-855c-065c250e2807", "type": "concept", "title": "Mizrahi Jews"}, {"id": "9ccd5e00-e370-497d-90c1-41703e3e68ea", "type": "concept", "title": "Baghdadi Jews"}, {"id": "6817ef38-cafa-46dc-8474-841a94f2fd05", "type": "concept", "title": "Yemenite Jews"}, {"id": "68e0db7f-7cf1-44ea-b540-cf631ce14c5c", "type": "concept", "title": "Moroccan Jews"}, {"id": "5197575e-2ff6-42ee-a9c8-748b942dc1db", "type": "concept", "title": "Persian Jews"}, {"id": "0769d5d3-0c9a-42eb-85db-dae2203440bc", "type": "concept", "title": "Beta Israel"}, {"id": "0f01b3d8-f184-4d7a-a0f5-307efd609029", "type": "concept", "title": "Cochin Jews"}, {"id": "23eb9959-ef1b-4ed4-83bf-ddb8cc7eb40e", "type": "concept", "title": "Kaifeng Jews"}], "description": "The point is to include Jewish histories from North Africa, the Middle East, Africa, India, and beyond."}]}, {"id": "536837d5-9e27-4787-9f3f-863a933fe35d", "type": "topic", "title": "Jews under Christianity and Islam", "description": "Jewish communities lived for centuries as minorities under Christian and Muslim rule. Students study legal status, cultural exchange, polemic, violence, coexistence, and negotiation.", "children": [{"id": "90aa9206-8585-4f72-a08e-e1351270b19b", "type": "subtopic", "title": "Jewish life under Islam", "children": [{"id": "8b55b175-0d13-436c-b137-1cb2ff6a69f9", "type": "concept", "title": "Dhimmi status"}, {"id": "1fb82455-0b6e-4b76-a405-cd03f0a4f2f1", "type": "concept", "title": "Jizya"}, {"id": "0140250a-336a-40a2-a5e0-4731b4d9bada", "type": "concept", "title": "Geniza"}, {"id": "a6079586-1a9b-46cb-9fd8-f5e0a3e3dba4", "type": "concept", "title": "Arabic Jewish culture"}, {"id": "5d51a220-cc4a-4cb2-9d25-b7e880df2a1b", "type": "concept", "title": "Islamic law"}, {"id": "c6b9db16-8efa-4934-9270-393266248bec", "type": "concept", "title": "Court physicians"}, {"id": "ce85ae95-a33c-41bb-aceb-a7b7add770ed", "type": "concept", "title": "Trade networks"}, {"id": "a05dc133-b7f6-47fd-bd13-80884e3cc8de", "type": "concept", "title": "Interreligious philosophy"}], "description": "Students learn both protections and constraints in Muslim-majority societies."}, {"id": "2e38c839-eedf-44a9-96d6-642b88efc053", "type": "subtopic", "title": "Jewish life under Christianity", "children": [{"id": "fc816160-d52f-4795-af2c-03aac4085df6", "type": "concept", "title": "Supersessionism"}, {"id": "9b788387-3391-41d9-b140-09a0f77e4588", "type": "concept", "title": "Disputations"}, {"id": "f26c74c4-a15b-4d71-bbd4-77817215805f", "type": "concept", "title": "Blood libel"}, {"id": "4a74e540-8bb7-43e2-917f-1b8ef7d80c2c", "type": "concept", "title": "Ghettos"}, {"id": "25908ae2-0102-4b27-bdb5-56da4bc6fd75", "type": "concept", "title": "Expulsions"}, {"id": "c1837809-2001-48cd-b32b-5c8479f6aec4", "type": "concept", "title": "Moneylending"}, {"id": "7e48fe3f-3506-466a-80d6-9bbf3b0df428", "type": "concept", "title": "Conversion pressure"}, {"id": "f9ac03c7-3f47-474f-917a-0589bbaa272a", "type": "concept", "title": "Anti-Judaism"}], "description": "Students examine theological, legal, economic, and social pressures in Christian Europe."}, {"id": "0747be74-8a45-4c4c-b8f7-53df41eddcc3", "type": "subtopic", "title": "Exchange and boundary-making", "children": [{"id": "31b2a9d7-522a-452d-98ea-77196ce3daa2", "type": "concept", "title": "Translation"}, {"id": "b2e8a8f1-1d65-4a2d-baf3-d314b7a76549", "type": "concept", "title": "Polemic"}, {"id": "e75a4659-ef27-45d5-b4a7-e22eb45823e4", "type": "concept", "title": "Shared spaces"}, {"id": "22e4be76-f51a-4e9a-9fd2-1c2f4b419b35", "type": "concept", "title": "Medical knowledge"}, {"id": "f2a6b9d5-d635-45ee-8f64-1a871bf4e916", "type": "concept", "title": "Music and poetry"}, {"id": "30b3230d-7416-4c03-93ae-fbdf360a5d9f", "type": "concept", "title": "Dietary boundaries"}, {"id": "a9c57a7a-4aa9-493f-b8a6-4af0b7dfc4a7", "type": "concept", "title": "Dress regulations"}, {"id": "17d6d727-3d8d-471f-a4a2-990b4e9bdaef", "type": "concept", "title": "Communal autonomy"}], "description": "The goal is to understand coexistence and conflict together."}]}, {"id": "d4c09439-49ff-4553-b58b-25d54d028c7b", "type": "topic", "title": "Modernity and Emancipation", "description": "Modernity transformed Jewish legal status, education, politics, religious authority, and identity. Students learn why emancipation opened new opportunities while creating new pressures to assimilate, reform, or redefine Jewish life.", "children": [{"id": "adb323f9-68a1-479c-a3f9-650ec80093ca", "type": "subtopic", "title": "Emancipation and citizenship", "children